                <div class="grid grid-cols-2 gap-2"><label :class="mode==='single'?'border-emerald-600 bg-emerald-50 text-emerald-800':'border-gray-200'" class="cursor-pointer rounded-xl border p-3"><input type="radio" name="mode" value="single" x-model="mode" @change="setMode('single')" class="sr-only"><b class="block text-sm">Theory ✓</b><span class="text-[10px] text-gray-500">Whole class studies together</span></label><label @click.prevent="if(canPractical)setMode('practical_split')" :class="mode==='practical_split'?'border-purple-600 bg-purple-50 text-purple-800':(canPractical?'border-gray-200':'cursor-not-allowed border-gray-100 bg-gray-50 opacity-50')" class="cursor-pointer rounded-xl border p-3"><input type="radio" name="mode" value="practical_split" x-model="mode" class="sr-only"><b class="block text-sm">Practical ✓</b><span class="text-[10px] text-gray-500" x-text="canPractical?'Half in Lab A, half in Lab B':'No practical subject available for this section'"></span></label></div>
                <template x-for="(group,index) in groups" :key="index"><section :class="mode==='practical_split'?'border-purple-200 bg-purple-50/50':'border-emerald-200 bg-emerald-50/40'" class="rounded-xl border p-3"><div class="mb-2 flex items-center justify-between"><b class="text-xs" x-text="mode==='practical_split'?'Group '+String.fromCharCode(65+index)+' · 50% students':'Whole class · 100% students'"></b><span class="rounded bg-white px-2 py-1 text-[9px] font-black" x-text="mode==='practical_split'?'PARALLEL LAB':'THEORY'"></span></div><div x-show="mode==='practical_split'" class="mb-2"><select :name="`groups[${index}][subject_offering_id]`" x-model="group.subject_offering_id" :required="mode==='practical_split'" class="w-full rounded-lg border border-purple-200 bg-white px-3 py-2 text-xs font-semibold outline-none transition-colors duration-300 hover:border-purple-300 focus:border-purple-600 focus:ring-2 focus:ring-purple-600/15"><option value="">Choose subject for this lab group</option><template x-for="subject in practicalSubjectsForSection" :key="subject.id"><option :value="String(subject.id)" x-text="subject.code+' · '+subject.name+(subject.is_elective?' · Elective':'')"></option></template></select></div><div class="grid gap-3 sm:grid-cols-[1fr_12rem]"><details class="overflow-hidden rounded-lg border bg-white" @toggle="if($event.target.open)loadTeachers(index)"><summary class="cursor-pointer px-3 py-2 text-xs font-black"><span x-text="group.teacher_ids.length?group.teacher_ids.length+' teacher(s) selected':'Choose teacher(s)'"></span><span class="float-right text-emerald-700">Search ▾</span></summary><div class="border-t p-2"><div class="relative"><input type="search" x-model="group.teacher_query" @input="queueTeacherSearch(index)" placeholder="Type teacher name or initials…" class="w-full rounded-lg border border-gray-200 py-2 pl-3 pr-9 text-xs font-semibold outline-none transition-colors duration-300 hover:border-gray-300 focus:border-[#1a5632] focus:ring-2 focus:ring-[#1a5632]/15"><span x-show="group.teacher_loading" class="absolute right-3 top-2 text-[10px] font-bold text-emerald-600">•••</span></div><div class="mt-2 grid max-h-44 gap-1 overflow-auto sm:grid-cols-2"><template x-for="teacher in group.teacher_options" :key="teacher.id"><label :class="group.teacher_ids.includes(String(teacher.id))?'bg-emerald-600 text-white ring-1 ring-emerald-600':'bg-gray-50 text-gray-600 hover:bg-emerald-50'" class="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-2 text-[10px] font-bold transition"><input type="checkbox" :name="`groups[${index}][teacher_ids][]`" :value="teacher.id" x-model="group.teacher_ids" class="sr-only"><span :class="group.teacher_ids.includes(String(teacher.id))?'bg-white text-emerald-700':'border border-gray-300 text-transparent'" class="grid h-4 w-4 shrink-0 place-items-center rounded text-[8px]">✓</span><span x-text="teacher.initials+' · '+teacher.name"></span></label></template><p x-show="!group.teacher_loading&&!group.teacher_options.length" class="p-2 text-[10px] font-bold text-amber-600">No teacher found.</p></div></div></details><div><select :name="`groups[${index}][routine_room_id]`" x-model="group.routine_room_id" :required="mode==='practical_split'" class="w-full rounded-lg border border-gray-200 px-2.5 py-2 text-xs font-semibold outline-none transition-colors duration-300 hover:border-gray-300 focus:border-[#1a5632] focus:ring-2 focus:ring-[#1a5632]/15"><option value="" x-text="mode==='practical_split'?'Choose laboratory':'Optional room'"></option><template x-for="room in rooms" :key="room.id"><option :value="String(room.id)" x-text="room.code+' · '+room.name"></option></template></select></div></div><input type="hidden" :name="`groups[${index}][group_label]`" :value="mode==='practical_split'?'Group '+String.fromCharCode(65+index):''"></section></template>
                <div><label class="text-[9px] font-black uppercase text-gray-500">Note</label><input name="notes" x-model="notes" placeholder="Optional routine note" class="mt-1 w-full rounded-lg border border-gray-200 px-3 py-2 text-xs outline-none transition-colors duration-300 hover:border-gray-300 focus:border-[#1a5632] focus:ring-2 focus:ring-[#1a5632]/15"></div>
                <div class="rounded-xl bg-amber-50 p-3 text-[10px] font-bold text-amber-700">Before saving, the system checks every selected teacher, laboratory, section, day and the complete start-to-end time range.</div>
            </div>
            <footer class="flex items-center justify-between border-t px-5 py-4"><button x-show="hasEntry" name="intent" value="delete" :disabled="saving" class="rounded-lg border border-red-200 px-4 py-2 text-xs font-black text-red-600 disabled:opacity-40">Clear class</button><span x-show="!hasEntry"></span><div class="flex gap-2"><button type="button" @click="$refs.editor.close()" class="rounded-lg border px-4 py-2 text-xs font-bold">Cancel</button><button name="intent" value="save" :disabled="saving" class="rounded-lg bg-[#1a5632] px-5 py-2 text-xs font-black text-white disabled:opacity-50"><span x-show="!saving">Save &amp; check conflicts</span><span x-show="saving" x-cloak>Checking…</span></button></div></footer>
        </form>
    </dialog>
    @endunless
</div>
@endsection
@push('scripts')
<script>
function routineEditor(entries,offerings,teachers,rooms,periods,day,allowPeriodRange,teacherUrl){return{
    entries,offerings,teachers,rooms,periods,day,allowPeriodRange,teacherUrl,sectionId:'',periodId:'',endPeriodId:'',sectionName:'',periodName:'',subjectOfferingId:'',mode:'single',notes:'',groups:[],hasEntry:false,lessonError:'',saving:false,
    blank(){return{subject_offering_id:'',teacher_ids:[],routine_room_id:'',group_label:'',teacher_query:'',teacher_options:[...this.teachers],teacher_loading:false,teacher_timer:null}},
    hydrateGroup(group){group.subject_offering_id=group.subject_offering_id||'';group.teacher_ids=(group.teacher_ids||[]).map(String);group.teacher_query='';group.teacher_options=[...this.teachers];group.teacher_loading=false;group.teacher_timer=null;return group},
    get subjectsForSection(){return this.offerings.filter(subject=>subject.section_ids.map(String).includes(String(this.sectionId)))},
    get practicalSubjectsForSection(){return this.subjectsForSection.filter(subject=>subject.has_practical)},
    get canPractical(){return this.practicalSubjectsForSection.length>0},
    get startPeriod(){return this.periods.find(period=>String(period.id)===String(this.periodId))},
    get availableEndPeriods(){const start=this.startPeriod;if(!start)return[];const result=[];for(const period of this.periods){if(period.position<start.position)continue;if(period.is_break){if(period.position>start.position)break;continue}result.push(period)}return result},
    openCell(sectionId,clickedPeriodId,sectionName,periodName){const entry=this.entries[`${sectionId}:${clickedPeriodId}`];this.lessonError='';this.saving=false;this.sectionId=sectionId;this.periodId=entry?.routine_period_id||clickedPeriodId;this.endPeriodId=entry?.end_routine_period_id||this.periodId;this.sectionName=sectionName;this.periodName=this.periods.find(period=>String(period.id)===String(this.periodId))?.name||periodName;this.hasEntry=!!entry;this.subjectOfferingId=entry?.subject_offering_id||'';this.mode=entry?.mode||'single';this.notes=entry?.notes||'';this.groups=entry?JSON.parse(JSON.stringify(entry.groups)).map(group=>this.hydrateGroup(group)):[this.blank()];this.setMode(this.mode,true);this.groups.forEach((group,index)=>this.loadTeachers(index));this.$refs.editor.showModal()},
    setMode(mode,preserve=false){if(mode==='practical_split'&&!this.canPractical)return;this.mode=mode;if(mode==='single'){const first=preserve&&this.groups[0]?this.groups[0]:this.groups[0]||this.blank();if(first.subject_offering_id)this.subjectOfferingId=first.subject_offering_id;this.groups=[first]}else{const first=this.groups[0]||this.blank();if(!first.subject_offering_id&&this.subjectOfferingId)first.subject_offering_id=this.subjectOfferingId;const second=preserve&&this.groups[1]?this.groups[1]:(this.groups[1]||this.blank());if(!second.subject_offering_id)second.subject_offering_id=first.subject_offering_id;this.groups=[first,second]}},
    queueTeacherSearch(index){const group=this.groups[index];clearTimeout(group.teacher_timer);group.teacher_timer=setTimeout(()=>this.loadTeachers(index),300)},
    async loadTeachers(index){const group=this.groups[index];if(!group)return;group.teacher_loading=true;const url=new URL(this.teacherUrl,window.location.origin);if(group.teacher_query)url.searchParams.set('q',group.teacher_query);group.teacher_ids.forEach(id=>url.searchParams.append('ids[]',id));try{const response=await fetch(url,{headers:{Accept:'application/json'}});const data=await response.json();if(!response.ok)throw new Error(data.message||'Could not load teachers');group.teacher_options=data.map(teacher=>({...teacher,id:String(teacher.id)}))}catch(error){this.lessonError=error.message}finally{group.teacher_loading=false}},
    async saveLesson(event){const submitter=event.submitter,intent=submitter?.value||'save';if(intent==='delete'&&!confirm('Clear this routine class?'))return;this.lessonError='';this.saving=true;const formData=new FormData(event.target);formData.set('intent',intent);try{const response=await fetch(event.target.action,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:formData});const data=await response.json();if(!response.ok){const errors=Object.values(data.errors||{}).flat();throw new Error(errors.length?errors.join(' '):(data.message||'The class could not be saved.'))}window.location.reload()}catch(error){this.lessonError=error.message;this.saving=false;this.$nextTick(()=>this.$refs.editor.scrollTo({top:0,behavior:'smooth'}))}},
    init(){if(@js(request()->boolean('settings') || $errors->has('section_ids') || $errors->has('routine_shift_id')))this.$nextTick(()=>this.$refs.settings?.showModal())},
    clock(value){if(!value)return'';const [hour,minute]=value.slice(0,5).split(':').map(Number);return`${hour%12||12}:${String(minute).padStart(2,'0')} ${hour<12?'AM':'PM'}`}
}}
</script>
@endpush
